package com.smartcanteen.entity;
import jakarta.persistence.*; import java.math.BigDecimal; import java.time.Instant; import java.util.*;
@Entity @Table(name="customer_orders",uniqueConstraints=@UniqueConstraint(columnNames="orderNumber"))
public class CustomerOrder { @Id @GeneratedValue(strategy=GenerationType.IDENTITY) private Long id; @Column(nullable=false,unique=true,length=40) private String orderNumber; @ManyToOne(fetch=FetchType.EAGER,optional=false) @JoinColumn(name="user_id",nullable=false) private AppUser user; @Column(nullable=false,precision=10,scale=2) private BigDecimal subtotal; @Column(nullable=false,precision=10,scale=2) private BigDecimal totalAmount; @Enumerated(EnumType.STRING) @Column(nullable=false,length=30) private OrderStatus orderStatus=OrderStatus.ORDER_PLACED; @Enumerated(EnumType.STRING) @Column(nullable=false,length=20) private PaymentStatus paymentStatus=PaymentStatus.CREATED; @Column(nullable=false,updatable=false) private Instant createdAt=Instant.now(); @Column(nullable=false) private Instant updatedAt=Instant.now(); @OneToMany(mappedBy="order",cascade=CascadeType.ALL,orphanRemoval=true) private List<OrderItem> items=new ArrayList<>(); @PreUpdate void touch(){updatedAt=Instant.now();} public void addItem(OrderItem i){items.add(i);i.setOrder(this);} public Long getId(){return id;} public String getOrderNumber(){return orderNumber;} public void setOrderNumber(String v){orderNumber=v;} public AppUser getUser(){return user;} public void setUser(AppUser v){user=v;} public BigDecimal getSubtotal(){return subtotal;} public void setSubtotal(BigDecimal v){subtotal=v;} public BigDecimal getTotalAmount(){return totalAmount;} public void setTotalAmount(BigDecimal v){totalAmount=v;} public OrderStatus getOrderStatus(){return orderStatus;} public void setOrderStatus(OrderStatus v){orderStatus=v;} public PaymentStatus getPaymentStatus(){return paymentStatus;} public void setPaymentStatus(PaymentStatus v){paymentStatus=v;} public Instant getCreatedAt(){return createdAt;} public Instant getUpdatedAt(){return updatedAt;} public List<OrderItem> getItems(){return items;} }
